import {REGIONS,REGION_TYPES,leadRegion,regionName,regionMatches,regionOptions} from './regions.mjs';
import {STATUS,SITE,FIELDS,NICHES,COUNTRIES,COUNTRY_FLAGS,norm,escape as esc,safeUrl,siteType,phoneNumber,opportunity,oppLabel,filterLeads,exportCsv,isDue,classifyNiche,leadCountry} from './core.mjs';
import {icon} from './icons.mjs';
const state={leads:[],events:[],imports:[],country:'BR',region:'',view:'all',filters:{q:'',city:'',status:'',site:'',contact:'',opp:'',niche:'',due:false},sort:'opportunity',page:1,selected:new Set(),demo:true,user:null,loading:false};
const navs=[['all','building','Todas as empresas'],['new','inbox','Novos leads'],['contacted','phone','Contatados'],['replied','message','Responderam'],['followup','clock','Follow-up'],['discarded','trash','Descartados'],['favorites','star','Favoritos']];
const app=document.querySelector('#app');
let toastTimer;
export function toast(message){const el=document.querySelector('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),4500);}
const options=(dict,value,first)=>`${first?`<option value="">${first}</option>`:''}${Object.entries(dict).map(([k,v])=>`<option value="${esc(k)}" ${value===k?'selected':''}>${esc(v)}</option>`).join('')}`;
const initials=name=>name.split(' ').filter(Boolean).slice(0,2).map(s=>s[0]).join('').toUpperCase();
const number=n=>Number(n||0).toLocaleString('pt-BR');
const date=v=>v?new Date(v).toLocaleString('pt-BR',{day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'}):'Não agendado';
const countryLeads=()=>state.leads.filter(l=>leadCountry(l)===state.country);
const scopedLeads=()=>countryLeads().filter(l=>regionMatches(l,state.region));
function regionNav(code){const leads=state.leads.filter(l=>leadCountry(l)===code);const entries=[['','Todas as regiões'],['unassigned','Sem região definida'],...REGIONS[code].map(r=>[r.code,r.name])];return `<div class="region-branch"><p class="region-heading">${REGION_TYPES[code]}</p><label class="region-search"><span class="sr-only">Buscar região</span><input type="search" id="region-search" placeholder="Buscar estado ou região" aria-label="Buscar estado ou região"></label><div class="region-items">${entries.map(([key,name])=>`<button class="nav-item region-item ${state.region===key?'active':''}" data-region="${key}" data-region-name="${esc(norm(name))}" ${state.region===key?'aria-current="page"':''}><span>${esc(name)}</span><span class="count">${leads.filter(l=>regionMatches(l,key)).length}</span></button>`).join('')}</div><p class="region-no-results" hidden>Nenhuma região encontrada</p></div>`;}
const count=view=>filterLeads(state.leads,{country:state.country,region:state.region},view).length;
const nicheIcon=n=>n==='aesthetics'?'spark':n==='real_estate'?'building':n==='health'?'shield':['food','hamburgers','pizzerias','restaurants'].includes(n)?'grid':'briefcase';
function visible(){const a=filterLeads(state.leads,{...state.filters,country:state.country,region:state.region},state.view);return a.sort((a,b)=>state.sort==='name'?a.name.localeCompare(b.name,'pt-BR'):state.sort==='rating'?(b.rating||0)-(a.rating||0):state.sort==='recent'?String(b.created_at).localeCompare(String(a.created_at)):state.sort==='followup'?(a.follow_up_at?Date.parse(a.follow_up_at):Infinity)-(b.follow_up_at?Date.parse(b.follow_up_at):Infinity):opportunity(b)-opportunity(a));}
function render(){const staticTitles={all:'Empresas',new:'Novos leads',contacted:'Contatados',replied:'Responderam',followup:'Follow-up',discarded:'Descartados',favorites:'Favoritos',imports:'Importações',settings:'Configurações'};const viewTitle=state.view.startsWith('niche:')?(NICHES[state.view.slice(6)]||'Nicho'):staticTitles[state.view];app.innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><span class="brand-mark">${icon('map')}</span>mapa<span style="font-weight:450;margin-left:-7px">leads</span></div><div class="workspace"><span class="workspace-avatar">${icon('building')}</span>Meu workspace ${icon('down')}</div><p class="nav-label">PAÍSES</p><nav class="nav-list country-list" aria-label="Países">${Object.entries(COUNTRIES).map(([code,name])=>`<button class="nav-item country-item ${state.country===code?'active':''}" data-country="${code}" ${state.country===code?'aria-current="page"':''} aria-expanded="${state.country===code}"><span class="country-flag">${COUNTRY_FLAGS[code]}</span>${name}<span class="count">${state.leads.filter(l=>leadCountry(l)===code).length}</span></button>${state.country===code?regionNav(code):''}`).join('')}</nav><div class="sidebar-divider"></div><p class="nav-label">PROSPECÇÃO</p><nav class="nav-list" aria-label="Áreas do CRM">${navs.map(([v,i,t])=>`<button class="nav-item ${state.view===v?'active':''}" data-nav="${v}" ${state.view===v?'aria-current="page"':''}>${icon(i)}${t}<span class="count">${count(v)}</span></button>`).join('')}</nav><div class="sidebar-divider"></div><p class="nav-label">NICHOS AUTOMÁTICOS</p><nav class="nav-list">${Object.entries(NICHES).filter(([v])=>['hamburgers','pizzerias','restaurants'].includes(v)||scopedLeads().some(l=>(l.niche||classifyNiche(l))===v)).map(([v,t])=>`<button class="nav-item ${state.view==='niche:'+v?'active':''}" data-nav="niche:${v}">${icon(nicheIcon(v))}${t}<span class="count">${count('niche:'+v)}</span></button>`).join('')||'<span class="muted small" style="padding:0 12px 10px">Aparecem após a importação</span>'}</nav><div class="sidebar-divider"></div><p class="nav-label">GERENCIAR</p><nav class="nav-list"><button class="nav-item ${state.view==='imports'?'active':''}" data-nav="imports">${icon('upload')}Importações</button></nav><div class="sidebar-bottom"><button class="nav-item ${state.view==='settings'?'active':''}" data-nav="settings">${icon('settings')}Configurações</button><div class="connection-card"><strong><span class="dot ${state.demo?'':'live'}"></span>${state.demo?'Banco desconectado':'Supabase conectado'}</strong><p>${state.demo?'Entre na sua conta para salvar os leads.':'Suas empresas em uma base única.'}</p>${state.demo?'<button class="text-button small" data-nav="settings" style="padding:5px 0;color:#2563eb">Conectar banco '+icon('arrow')+'</button>':''}</div></div></aside><main class="main"><div class="topbar"><div class="breadcrumb"><button class="text-button mobile-menu" data-action="menu" aria-label="Abrir menu">${icon('menu')}</button><span>Workspace</span>${icon('chevron')}<strong>${COUNTRIES[state.country]}</strong>${state.region?icon('chevron')+'<strong>'+esc(regionName(state.country,state.region))+'</strong>':''}</div><div class="topbar-right">${state.demo?'<span class="demo-tag">Base vazia</span>':'<span class="small">'+icon('shield')+' Base conectada</span>'}<button class="text-button" data-nav="followup" aria-label="Ver follow-ups">${icon('clock')}</button><span class="avatar-user">${state.user?esc(initials(state.user.email||'EU')):'EU'}</span></div></div><div class="content"><header class="page-header"><div><h1>${viewTitle}${state.view==='settings'?'':' · '+COUNTRIES[state.country]+(!['imports','settings'].includes(state.view)&&state.region?' · '+esc(regionName(state.country,state.region)):'')}</h1><p>${state.view.startsWith('niche:')?'Leads classificados automaticamente a partir do nome e da categoria da empresa.':({all:'Encontre boas oportunidades. Transforme empresas em clientes.',new:'Empresas prontas para o primeiro contato.',contacted:'Acompanhe as empresas que você já abordou.',replied:'Continue as conversas com quem respondeu.',followup:'O próximo contato, na hora certa.',discarded:'Leads arquivados, sem perder o histórico.',favorites:'Suas oportunidades prioritárias em um só lugar.',imports:'Todas as planilhas que passaram pelo seu CRM.',settings:'Conecte sua base de empresas e gerencie seu acesso.'})[state.view]}</p></div>${!['settings'].includes(state.view)?`<div class="header-actions"><button data-action="export">${icon('download')}Exportar CSV</button><button class="primary" data-action="import">${icon('upload')}Importar planilha</button></div>`:''}</header><div id="view-content">${state.view==='imports'?renderImports():state.view==='settings'?'<div id="settings-content"></div>':renderWorkspace()}</div></div></main></div>`;if(state.view==='settings')void loadSettings();}
function renderWorkspace(){const all=scopedLeads();const rated=all.filter(l=>l.rating!==null);const stats=[['Leads totais',number(all.length),'Empresas na sua base','building',''],['Alta oportunidade',number(all.filter(l=>oppLabel(l)==='Alta').length),'Potencial para criação de site','spark','green'],['Sem site próprio',number(all.filter(l=>['missing','social','platform'].includes(siteType(l.website))).length),'Inclui redes sociais e plataformas','globe','amber'],['Telefone válido',number(all.filter(l=>phoneNumber(l.phone,leadCountry(l))).length),'Formato pronto para contato','phone',''],['Nota média',rated.length?(rated.reduce((s,l)=>s+Number(l.rating),0)/rated.length).toLocaleString('pt-BR',{minimumFractionDigits:2,maximumFractionDigits:2}):'—','Avaliações do Google Maps','star','']];return `<section class="stats" aria-label="Resumo da base">${stats.map(([label,value,note,i,c])=>`<div class="stat"><div class="stat-top">${label}${icon(i)}</div><div class="stat-value ${c}">${value}</div><p class="stat-note">${note}</p></div>`).join('')}</section><section class="filter-panel" aria-label="Buscar e filtrar empresas"><div class="search-row"><div class="search-box">${icon('search')}<input id="search" type="search" placeholder="Buscar empresa, cidade, endereço ou telefone..." aria-label="Buscar empresas" value="${esc(state.filters.q)}"></div><button class="quick-filter ${state.filters.site==='without'?'selected':''}" data-action="without">${icon('globe')}Sem site próprio</button><button class="quick-filter ${state.filters.due?'selected':''}" data-action="due">${icon('clock')}Follow-ups pendentes <span class="small">${all.filter(l=>isDue(l)).length}</span></button></div><div class="filter-row"><select aria-label="Cidade" data-filter="city">${options(Object.fromEntries([...new Set(all.map(l=>l.city).filter(Boolean))].sort().map(x=>[x,x])),state.filters.city,'Todas as cidades')}</select><select aria-label="Status" data-filter="status">${options(STATUS,state.filters.status,'Todos os status')}</select><select aria-label="Oportunidade" data-filter="opp">${options({'Alta':'Alta oportunidade','Média':'Média oportunidade','Baixa':'Baixa oportunidade'},state.filters.opp,'Toda oportunidade')}</select><select aria-label="Presença de site" data-filter="site">${options({without:'Sem site próprio',...SITE},state.filters.site,'Com ou sem site')}</select><select aria-label="Nicho" data-filter="niche">${options(NICHES,state.filters.niche,'Todos os nichos')}</select><select aria-label="Contato" data-filter="contact">${options({yes:'Com telefone válido',no:'Sem telefone válido'},state.filters.contact,'Qualquer contato')}</select><button class="text-button" data-action="clear">Limpar filtros</button></div></section><section class="table-card" aria-label="Lista de leads" id="table-region">${renderTable()}</section><div class="bottom-note"><span>${icon('shield')}${state.demo?'Entre na sua conta para salvar empresas e acompanhamento.':'Histórico preservado ao importar novamente a mesma empresa.'}</span><span>${icon('globe')}Sem site no Maps não confirma ausência de site.</span></div>`;}
function renderTable(){const rows=visible();const pages=Math.max(1,Math.ceil(rows.length/10));state.page=Math.min(state.page,pages);const subset=rows.slice((state.page-1)*10,state.page*10);return `<div class="table-toolbar"><div><strong>${state.view.startsWith('niche:')?(NICHES[state.view.slice(6)]||'Nicho'):state.view==='all'?'Todas as empresas':navs.find(n=>n[0]===state.view)?.[2]}</strong><span class="result-count">${rows.length} leads</span></div><div class="toolbar-actions"><button data-action="copy-visible">${icon('copy')}Copiar visíveis</button><select id="sort" aria-label="Ordenar leads">${options({opportunity:'Ordenar: oportunidade',name:'Ordenar: nome',rating:'Ordenar: nota Google',recent:'Ordenar: mais recentes',followup:'Ordenar: próximo contato'},state.sort)}</select></div></div>${state.selected.size?`<div class="selection-bar"><span>${state.selected.size} selecionado(s)</span><select id="bulk-status" aria-label="Mover leads selecionados">${options(STATUS,'','Mover para...')}</select><select id="bulk-region" aria-label="Definir região dos leads selecionados">${regionOptions(state.country,'','Definir estado / região…')}</select><button class="text-button" data-action="deselect">Cancelar seleção</button></div>`:''}<div class="table-scroll"><table><thead><tr><th><input type="checkbox" id="select-page" aria-label="Selecionar página" ${subset.length&&subset.every(l=>state.selected.has(l.id))?'checked':''}></th><th aria-label="Favorito"></th><th>EMPRESA</th><th>OPORTUNIDADE</th><th>GOOGLE</th><th>SITE</th><th>NICHO</th><th>CONTATOS RÁPIDOS</th><th>STATUS</th><th aria-label="Detalhes"></th></tr></thead><tbody>${subset.length?subset.map((l,i)=>renderRow(l,i)).join(''):`<tr><td colspan="10"><div class="empty"><div class="empty-icon">${icon('search')}</div><h3>${state.loading?'Carregando sua base…':'Nenhuma empresa por aqui'}</h3><p>${state.loading?'Aguarde enquanto buscamos seus leads.':countryLeads().length?'Ajuste os filtros ou mova empresas para esta área.':`Importe a primeira planilha de ${COUNTRIES[state.country]} para começar.`}</p><button ${state.loading?'disabled':''} data-action="${countryLeads().length?'clear':'import'}">${countryLeads().length?'Limpar filtros':'Importar planilha'}</button></div></td></tr>`}</tbody></table></div><footer class="pagination"><span>${rows.length?`${(state.page-1)*10+1}–${Math.min(state.page*10,rows.length)} de ${rows.length} empresas`:'0 empresas'}</span><div class="pagination-controls"><button data-action="prev" aria-label="Página anterior" ${state.page===1?'disabled':''}>${icon('left')}</button><button class="page-number" aria-label="Página atual">${state.page}</button><span>de ${pages}</span><button data-action="next" aria-label="Próxima página" ${state.page===pages?'disabled':''}>${icon('chevron')}</button></div></footer>`;}
function contactLinks(l){const phone=phoneNumber(l.phone,leadCountry(l));const maps=safeUrl(l.maps_url)||`https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(l.name+' '+l.address+' '+l.city)}`;return `<div class="contact-actions">${l.phone?`<button data-copy-phone="${esc(l.id)}" title="Copiar telefone" aria-label="Copiar telefone de ${esc(l.name)}">${icon('copy')}</button>`:''}${phone?`<a class="wa" href="https://wa.me/${phone}" target="_blank" rel="noopener noreferrer" title="Abrir WhatsApp — não envia mensagem automaticamente">${icon('message')}WhatsApp</a>`:'<span class="muted small">Sem telefone</span>'}<a href="${esc(maps)}" target="_blank" rel="noopener noreferrer" title="Abrir Google Maps" aria-label="Abrir ${esc(l.name)} no Maps">${icon('pin')}</a>${safeUrl(l.website)?`<a href="${esc(safeUrl(l.website))}" target="_blank" rel="noopener noreferrer" title="Abrir link informado">${icon('globe')}</a>`:''}</div>`;}
function renderRow(l,i){const score=opportunity(l),type=siteType(l.website);return `<tr><td><input type="checkbox" data-select="${esc(l.id)}" aria-label="Selecionar ${esc(l.name)}" ${state.selected.has(l.id)?'checked':''}></td><td><button class="star-button ${l.favorite?'is-fav':''}" data-favorite="${esc(l.id)}" aria-label="${l.favorite?'Remover dos':'Adicionar aos'} favoritos: ${esc(l.name)}" aria-pressed="${!!l.favorite}">${icon('star')}</button></td><td><div class="lead-cell"><span class="lead-avatar tone${i%4}">${esc(initials(l.name))}</span><div><button class="lead-name" data-detail="${esc(l.id)}" title="${esc(l.name)}">${esc(l.name)}</button><p class="lead-meta">${esc(l.city||'Cidade não informada')}${l.state?' · '+esc(leadRegion(l)?regionName(leadCountry(l),leadRegion(l)):l.state):''}</p></div></div></td><td title="Pontuação: presença de site (40), telefone (20), nota (20) e avaliações (20)."><div class="score ${score<45?'low':score<75?'mid':''}"><span class="score-dot"></span>${oppLabel(l)}<span class="score-number">· ${score}</span></div></td><td><div class="rating">${icon('star')}${l.rating!==null?Number(l.rating).toLocaleString('pt-BR'):'—'}</div><p class="reviews">${number(l.reviews)} avaliações</p></td><td><span class="badge ${type}">${type==='missing'?'Sem site informado':SITE[type]}</span></td><td><select class="niche-select" data-niche="${esc(l.id)}" aria-label="Nicho de ${esc(l.name)}">${options(NICHES,l.niche||classifyNiche(l))}</select></td><td>${contactLinks(l)}</td><td><select class="status-select ${l.status}" data-status="${esc(l.id)}" aria-label="Status de ${esc(l.name)}">${options(STATUS,l.status)}</select>${l.follow_up_at&&l.status!=='discarded'?`<span class="due-label">${isDue(l)?'Pendente · ':''}${date(l.follow_up_at)}</span>`:''}</td><td><button class="detail-button" data-detail="${esc(l.id)}" title="Detalhes" aria-label="Detalhes de ${esc(l.name)}">${icon('panel')}</button></td></tr>`;}
function renderImports(){const imports=state.imports.filter(b=>(b.country_code||'BR')===state.country);return `<div class="notice blue" style="margin-bottom:20px">${icon('file')} Aceita Excel (.xlsx e .xls), CSV e TSV. Empresas repetidas são atualizadas preservando o acompanhamento comercial.</div><div class="table-card"><div class="table-scroll"><table><thead><tr><th>ARQUIVO</th><th>IMPORTADO EM</th><th>NOVAS</th><th>ATUALIZADAS</th><th>IGNORADAS</th></tr></thead><tbody>${imports.length?imports.map(b=>`<tr><td style="padding-left:20px">${icon('file')} ${esc(b.filename)}</td><td>${date(b.created_at)}</td><td>${b.created_count}</td><td>${b.updated_count}</td><td>${b.skipped_count}</td></tr>`).join(''):'<tr><td colspan="5"><div class="empty"><div class="empty-icon">'+icon('upload')+'</div><h3>Sua base começa com uma planilha</h3><p>Revise as colunas antes de importar. O CRM identifica empresas que já estão na sua base.</p><button class="primary" data-action="import">'+icon('upload')+'Importar primeira planilha</button></div></td></tr>'}</tbody></table></div></div>`;}
function refreshTable(){const el=document.querySelector('#table-region');if(el)el.innerHTML=renderTable();}
function navigate(view){state.view=view;state.page=1;state.selected.clear();state.filters={q:'',city:'',status:'',site:'',contact:'',opp:'',niche:'',due:false};render();}
async function copy(text){try{await navigator.clipboard.writeText(text);toast('Copiado para a área de transferência.');}catch{toast('O navegador bloqueou a cópia. Use a exportação CSV.');}}
function download(text,filename,type='text/csv;charset=utf-8'){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
const leadText=leads=>leads.map(l=>`${l.name} | ${l.city} | ${l.phone||'Sem telefone'} | ${SITE[siteType(l.website)]} | ${STATUS[l.status]}`).join('\n');
async function updateLeads(ids,patch){const {updateRecords}=await import('./store.mjs');await updateRecords(state,ids,patch);render();}
async function openDetail(id){const {showDetail}=await import('./detail.mjs');showDetail({state,id,updateLeads,toast,icon,esc,date,contactLinks,copy,leadText});}
async function openImport(){const {showImport}=await import('./import.mjs');showImport({state,toast,render,navigate,download});}
async function loadSettings(){const {showSettings}=await import('./settings.mjs');showSettings({state,render,toast});}
app.addEventListener('input',e=>{if(e.target.id==='region-search'){const query=norm(e.target.value);const buttons=[...app.querySelectorAll('[data-region]')];buttons.forEach(b=>b.hidden=!!query&&!b.dataset.regionName.includes(query));app.querySelector('.region-no-results').hidden=buttons.some(b=>!b.hidden);return;}if(e.target.id==='search'){state.filters.q=e.target.value;state.page=1;state.selected.clear();refreshTable();}});
app.addEventListener('change',async e=>{const t=e.target;try{if(t.id==='bulk-region'&&t.value){await updateLeads([...state.selected],{state:t.value});state.selected.clear();render();}else if(t.dataset.filter){state.filters[t.dataset.filter]=t.value;state.page=1;state.selected.clear();render();}else if(t.id==='sort'){state.sort=t.value;refreshTable();}else if(t.dataset.niche){await updateLeads([t.dataset.niche],{niche:t.value});}else if(t.dataset.status){if(t.value==='followup'){await openDetail(t.dataset.status);document.querySelector('#detail-status').value='followup';document.querySelector('#detail-date').focus();refreshTable();}else await updateLeads([t.dataset.status],{status:t.value});}else if(t.dataset.select){t.checked?state.selected.add(t.dataset.select):state.selected.delete(t.dataset.select);refreshTable();}else if(t.id==='select-page'){visible().slice((state.page-1)*10,state.page*10).forEach(l=>t.checked?state.selected.add(l.id):state.selected.delete(l.id));refreshTable();}else if(t.id==='bulk-status'&&t.value){if(t.value==='followup'){toast('Abra os detalhes de cada lead para agendar o próximo contato.');t.value='';return;}await updateLeads([...state.selected],{status:t.value});state.selected.clear();render();}}catch(err){toast(err.message);render();}});
app.addEventListener('click',async e=>{const b=e.target.closest('button,[data-nav]');if(!b)return;try{if(Object.hasOwn(b.dataset,'region')){state.region=b.dataset.region;navigate('all');document.querySelector('.sidebar')?.classList.remove('open');return;}if(b.dataset.country){state.country=b.dataset.country;state.region='';navigate('all');if(matchMedia('(max-width: 760px)').matches)document.querySelector('.sidebar')?.classList.add('open');return;}if(b.dataset.nav){navigate(b.dataset.nav);return;}if(b.dataset.detail){await openDetail(b.dataset.detail);return;}if(b.dataset.favorite){const l=state.leads.find(l=>l.id===b.dataset.favorite);await updateLeads([l.id],{favorite:!l.favorite});return;}if(b.dataset.copyPhone){await copy(state.leads.find(l=>l.id===b.dataset.copyPhone).phone);return;}switch(b.dataset.action){case'menu':document.querySelector('.sidebar').classList.toggle('open');break;case'import':await openImport();break;case'export':download(exportCsv(['imports','settings'].includes(state.view)?countryLeads():visible()),'empresas-'+new Date().toISOString().slice(0,10)+'.csv');toast('CSV exportado com os filtros atuais.');break;case'copy-visible':await copy(leadText(visible()));break;case'without':state.filters.site=state.filters.site==='without'?'':'without';state.page=1;state.selected.clear();render();break;case'due':state.filters.due=!state.filters.due;state.page=1;state.selected.clear();render();break;case'clear':state.filters={q:'',city:'',status:'',site:'',contact:'',opp:'',due:false};state.page=1;state.selected.clear();render();break;case'prev':state.page--;refreshTable();break;case'next':state.page++;refreshTable();break;case'deselect':state.selected.clear();refreshTable();break;}}catch(err){toast(err.message||'Não foi possível concluir a ação.');}});
app.addEventListener('click',e=>{if(e.target.closest('[data-action="clear"]'))queueMicrotask(()=>{state.filters.niche='';});});
const publicCopyObserver=new MutationObserver(()=>{app.querySelectorAll('.connection-card p,.bottom-note span').forEach(el=>{if(el.textContent.includes('Entre na sua conta'))el.childNodes.forEach(n=>{if(n.nodeType===3)n.textContent=n.textContent.replace('Entre na sua conta para salvar os leads.','Execute o schema para ativar o banco público.').replace('Entre na sua conta para salvar empresas e acompanhamento.','Execute o schema para ativar o banco público.');});});});publicCopyObserver.observe(app,{childList:true,subtree:true});
render();
import('./store.mjs').then(async({initialize})=>{await initialize(state,()=>render(),toast);}).catch(()=>toast('Não foi possível iniciar a conexão. Abra Configurações.'));
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'search_crm_companies',title:'Buscar empresas no CRM',description:'Filtra empresas importadas por nome, cidade ou telefone e exibe os resultados no CRM.',inputSchema:{type:'object',properties:{query:{type:'string'}},required:['query'],additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute(input){if(typeof input?.query!=='string'||Object.keys(input).some(k=>k!=='query'))throw new Error('Informe apenas query como texto.');navigate('all');state.filters.q=input.query;render();return {count:visible().length,companies:visible().slice(0,30).map(l=>({id:l.id,name:l.name,city:l.city,website_status:SITE[siteType(l.website)],status:STATUS[l.status]}))};}})).catch(()=>{});}catch{}}
